#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <stdexcept>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses OpenMP to compute in parallel.

   Notes:
   - Uses Jacobi iteration with diagonal extraction.
   - Correct under every thread count: no shared element is written by multiple threads without protection.
*/
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size must be N");
    x.assign(N, 0.0);

    // Extract diagonal (single-thread; avoids races and handles duplicate diagonal entries deterministically).
    std::vector<double> diag(N, 0.0);
    for (const auto& e : A) {
        if (e.row >= N || e.column >= N) throw std::invalid_argument("COO index out of bounds");
        if (e.row == e.column) diag[e.row] += e.value;
    }

    // Require nonzero diagonal for Jacobi.
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry; Jacobi cannot proceed");
    }

    // Pre-bucket COO entries by row to avoid atomics during SpMV-like accumulation.
    // Also combine duplicates implicitly during accumulation.
    std::vector<std::vector<COOElement>> rows(N);
    rows.assign(N, {});
    rows.shrink_to_fit(); // no-op for correctness; keeps function self-contained

    rows.resize(N);
    for (const auto& e : A) {
        rows[e.row].push_back(e);
    }

    std::vector<double> x_old(N, 0.0);

    const size_t maxIters = 10000;
    const double tol = 1e-12;

    for (size_t iter = 0; iter < maxIters; ++iter) {
        x_old = x;

        double maxDiff = 0.0;

        #pragma omp parallel for reduction(max:maxDiff) schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
            // Compute sum_{j != i} A_ij * x_old[j]
            double offDiagSum = 0.0;
            for (const auto& e : rows[static_cast<size_t>(i)]) {
                if (e.column != static_cast<size_t>(i)) {
                    offDiagSum += e.value * x_old[e.column];
                }
            }

            const double newXi = (b[static_cast<size_t>(i)] - offDiagSum) / diag[static_cast<size_t>(i)];
            const double diff = std::fabs(newXi - x_old[static_cast<size_t>(i)]);

            x[static_cast<size_t>(i)] = newXi; // unique per i: safe without atomics/critical
            if (diff > maxDiff) maxDiff = diff;
        }

        if (maxDiff < tol) break;
    }
}
